const ALIASES=Object.freeze({AVLO:'AVArato',Avlo:'AVArato',avlo:'AVArato',Talgo:'Tardo',CAF:'KAFKA',Siemens:'Schlimmens',Alstom:'Malstom',Lowgo:'OuiOui',Rossa:'YaIré',Renfe:'Tenfe','Licitación de Renfe':'Tenfe','Licitación de Tenfe':'Tenfe'});
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function brandName(value){const name=String(value??'');return Object.hasOwn(ALIASES,name)?ALIASES[name]:name;}
export function brandLogo(value,options=''){
  const name=brandName(value),opts=typeof options==='string'?{className:options}:options||{};
  const className='brand-logo'+(opts.className?' '+String(opts.className):'');
  if(!Object.hasOwn(BRANDS,name))return `<span class="${escapeHTML(className)}">${escapeHTML(name)}</span>`;
  const meta=BRANDS[name],variant=['white','dark'].includes(opts.variant)?opts.variant:'color';
  const primary=variant==='white'?'#ffffff':variant==='dark'?'#263c40':meta.color;
  const accent=variant==='white'?(name==='Trenespop'?'#00bfa6':name==='OuiOui'?'#0559a2':name==='AVArato'?meta.accent:'#ffffff'):variant==='dark'?(name==='Trenespop'?'#ffffff':name==='OuiOui'?'#ffffff':'#263c40'):meta.accent;
  const art=ART[name].replaceAll('@primary',primary).replaceAll('@accent',accent);
  const accessible=opts.decorative?'aria-hidden="true"':`role="img" aria-label="${escapeHTML(name)}"`;
  return `<svg xmlns="http://www.w3.org/2000/svg" class="${escapeHTML(className)}" viewBox="0 0 240 80" width="240" height="80" ${accessible} focusable="false" style="display:block;max-width:100%;height:auto;"><title>${escapeHTML(name)}</title>${art}</svg>`;
}
